-- Durable entity identity and shared attachments (ADR 0006).
-- Generated by the PR that ships it; the runbook is
-- docs/runbooks/entity-identity-schema.md. Run entity-identity.preflight.sql
-- first and stop on any row it returns. Run this in Neon BEFORE merging the
-- PR: everything here is additive, and the triggers keep old code's writes
-- consistent until the new build deploys. The legacy image joins, the cover
-- and logo columns, `Image.targetType`/`targetId`/`idempotencyKey`, and the
-- `dataExceptions` columns stay until entity-identity.drop.sql.
--
-- One transaction. Entity tables are locked against writes (reads continue)
-- so no row is created between its backfill and its identity FK.

BEGIN;

LOCK TABLE "Cookbook", "Device", "Expense", "FinancialAccount", "FinancialTransaction", "GardenEntry", "Image", "ImageSighting", "ImportRun", "Ingredient", "InventoryEntry", "LedgerParty", "LedgerTransfer", "Location", "Meal", "Plant", "Planting", "Product", "ProductCategory", "Project", "Purchase", "Recipe", "Task", "Vendor", "VendorAccount", "Wish",
  "ProductImage", "LocationImage", "GardenEntryImage", "RecipeImage",
  "MealImage", "TaskImage", "PurchaseImage", "ProjectImage",
  "AuditLog", "SearchDocument", "EntityEmbedding", "PhotoGroupProposal"
IN EXCLUSIVE MODE;

-- 1. Identity.
CREATE TABLE "Entity" (
	"id" uuid PRIMARY KEY NOT NULL,
	"kind" text NOT NULL,
	"shortcode" text,
	"createdAt" timestamp DEFAULT now() NOT NULL,
	"deletedAt" timestamp,
	"mergedIntoId" uuid,
	CONSTRAINT "Entity_id_shortcode_key" UNIQUE("id","shortcode"),
	CONSTRAINT "Entity_id_kind_key" UNIQUE("id","kind"),
	CONSTRAINT "Entity_kind_check" CHECK ("Entity"."kind" IN ('product', 'recipe', 'ingredient', 'cookbook', 'location', 'inventory', 'meal', 'ledgerParty', 'ledgerTransfer', 'project', 'task', 'vendor', 'purchase', 'financialAccount', 'financialTransaction', 'wish', 'expense', 'image', 'planting', 'gardenEntry', 'vendorAccount', 'productCategory', 'importRun', 'device', 'imageSighting', 'plant')),
	CONSTRAINT "Entity_shortcode_prefix_check" CHECK ("Entity"."shortcode" IS NULL OR CASE "Entity"."kind" WHEN 'product' THEN "Entity"."shortcode" LIKE 'PRD-%' WHEN 'recipe' THEN "Entity"."shortcode" LIKE 'RCP-%' WHEN 'ingredient' THEN "Entity"."shortcode" LIKE 'ING-%' WHEN 'cookbook' THEN "Entity"."shortcode" LIKE 'CKB-%' WHEN 'location' THEN "Entity"."shortcode" LIKE 'LOC-%' WHEN 'inventory' THEN "Entity"."shortcode" LIKE 'INV-%' WHEN 'meal' THEN "Entity"."shortcode" LIKE 'MEL-%' WHEN 'ledgerParty' THEN "Entity"."shortcode" LIKE 'LPY-%' WHEN 'ledgerTransfer' THEN "Entity"."shortcode" LIKE 'LTR-%' WHEN 'project' THEN "Entity"."shortcode" LIKE 'PRJ-%' WHEN 'task' THEN "Entity"."shortcode" LIKE 'TSK-%' WHEN 'vendor' THEN "Entity"."shortcode" LIKE 'VEN-%' WHEN 'purchase' THEN "Entity"."shortcode" LIKE 'PUR-%' WHEN 'financialAccount' THEN "Entity"."shortcode" LIKE 'FAC-%' WHEN 'financialTransaction' THEN "Entity"."shortcode" LIKE 'FTX-%' WHEN 'wish' THEN "Entity"."shortcode" LIKE 'WSH-%' WHEN 'expense' THEN "Entity"."shortcode" LIKE 'EXP-%' WHEN 'image' THEN "Entity"."shortcode" LIKE 'IMG-%' WHEN 'planting' THEN "Entity"."shortcode" LIKE 'PLT-%' WHEN 'gardenEntry' THEN "Entity"."shortcode" LIKE 'GDE-%' WHEN 'vendorAccount' THEN "Entity"."shortcode" LIKE 'VACCT-%' WHEN 'productCategory' THEN "Entity"."shortcode" LIKE 'CAT-%' WHEN 'importRun' THEN "Entity"."shortcode" LIKE 'RUN-%' WHEN 'device' THEN "Entity"."shortcode" LIKE 'DEV-%' WHEN 'imageSighting' THEN "Entity"."shortcode" LIKE 'IMS-%' WHEN 'plant' THEN "Entity"."shortcode" LIKE 'PLANT-%' ELSE false END),
	CONSTRAINT "Entity_merge_not_self_check" CHECK ("Entity"."mergedIntoId" IS NULL OR "Entity"."mergedIntoId" <> "Entity"."id"),
	CONSTRAINT "Entity_merged_is_deleted_check" CHECK ("Entity"."mergedIntoId" IS NULL OR "Entity"."deletedAt" IS NOT NULL),
	CONSTRAINT "Entity_live_has_shortcode_check" CHECK ("Entity"."deletedAt" IS NOT NULL OR "Entity"."shortcode" IS NOT NULL)
);

CREATE UNIQUE INDEX "Entity_shortcode_unique" ON "Entity" USING btree ("shortcode");
CREATE INDEX "Entity_mergedIntoId_idx" ON "Entity" USING btree ("mergedIntoId");

