-- Repair: an early-2026 import bug filed Product create and update entries
-- under 'inventory' with the Product's id. The id is authoritative; only the
-- kind label is wrong, and the identity FK would reject it.
UPDATE "AuditLog" a
SET "entityType" = 'product'
WHERE a."entityType" = 'inventory'
  AND (
    EXISTS (SELECT 1 FROM "Product" p WHERE p."id" = a."entityId")
    OR EXISTS (
      SELECT 1 FROM "AuditLog" b
      WHERE b."entityId" = a."entityId" AND b."entityType" = 'product'
    )
  );

-- History and projection rows that name an identity no payload holds any
-- more (a hard-deleted row) get a code-less tombstone rather than a
-- fabricated code, so their identity FK can be enforced.
INSERT INTO "Entity" ("id", "kind", "shortcode", "createdAt", "deletedAt")
SELECT DISTINCT ON (x."id") x."id", x."kind", NULL, x."at", x."at"
FROM (
  SELECT "entityId" AS "id", "entityType" AS "kind", "createdAt" AS "at" FROM "AuditLog"
  UNION ALL
  SELECT "entityId", "entityType", "createdAt" FROM "SearchDocument"
  UNION ALL
  SELECT "entityId", "entityType", "createdAt" FROM "EntityEmbedding"
) x
WHERE x."kind" IN ('cookbook', 'device', 'expense', 'financialAccount', 'financialTransaction', 'gardenEntry', 'image', 'imageSighting', 'importRun', 'ingredient', 'inventory', 'ledgerParty', 'ledgerTransfer', 'location', 'meal', 'plant', 'planting', 'product', 'productCategory', 'project', 'purchase', 'recipe', 'task', 'vendor', 'vendorAccount', 'wish')
  AND NOT EXISTS (SELECT 1 FROM "Entity" e WHERE e."id" = x."id")
ORDER BY x."id", x."at";

ALTER TABLE "Entity" ADD CONSTRAINT "Entity_mergedIntoId_Entity_id_fk" FOREIGN KEY ("mergedIntoId") REFERENCES "public"."Entity"("id") ON DELETE no action ON UPDATE no action;

-- Merge redirects from the survivors' audit evidence: each merge writes an
-- update entry on the survivor whose `changes.mergedFrom.to` lists the loser
-- ids. Ingredient merges record alias strings and hard-delete their losers,
-- so they cannot be reconstructed and are left as plain tombstones.
UPDATE "Entity" e
SET "mergedIntoId" = a."entityId"
FROM "AuditLog" a
CROSS JOIN LATERAL jsonb_array_elements_text(
  CASE WHEN jsonb_typeof(a."changes"->'mergedFrom'->'to') = 'array'
    THEN a."changes"->'mergedFrom'->'to' ELSE '[]'::jsonb END
) loser
WHERE a."action" = 'update'
  AND a."changes" ? 'mergedFrom'
  AND loser ~ '^[0-9a-f-]{36}$'
  AND e."id" = loser::uuid
  AND e."kind" = a."entityType"
  AND e."id" <> a."entityId"
  AND e."deletedAt" IS NOT NULL
  AND e."mergedIntoId" IS NULL;

-- Path-compress so every redirect is one hop to the final survivor.
DO $$
DECLARE
  changed integer;
  rounds integer := 0;
BEGIN
  LOOP
    UPDATE "Entity" e
    SET "mergedIntoId" = s."mergedIntoId"
    FROM "Entity" s
    WHERE e."mergedIntoId" = s."id" AND s."mergedIntoId" IS NOT NULL;
    GET DIAGNOSTICS changed = ROW_COUNT;
    EXIT WHEN changed = 0;
    rounds := rounds + 1;
    IF rounds > 20 THEN
      RAISE EXCEPTION 'merge redirects do not converge: a cycle in merge evidence';
    END IF;
  END LOOP;
END $$;

-- 2. Attachments.
CREATE TABLE "EntityAttachment" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"subjectEntityId" uuid NOT NULL,
	"imageId" uuid NOT NULL,
	"role" text DEFAULT 'attachment' NOT NULL,
	"sortOrder" integer DEFAULT 0 NOT NULL,
	"purpose" text,
	"documentKind" text,
	"idempotencyKey" text,
	"createdAt" timestamp DEFAULT now() NOT NULL,
	"updatedAt" timestamp DEFAULT now() NOT NULL,
	"deletedAt" timestamp,
	CONSTRAINT "EntityAttachment_role_check" CHECK ("EntityAttachment"."role" IN ('attachment', 'cover', 'logo')),
	CONSTRAINT "EntityAttachment_purpose_check" CHECK ("EntityAttachment"."purpose" IS NULL OR "EntityAttachment"."purpose" IN ('item', 'label'))
);

CREATE UNIQUE INDEX "EntityAttachment_subject_image_key" ON "EntityAttachment" USING btree ("subjectEntityId","imageId") WHERE "EntityAttachment"."deletedAt" IS NULL;
CREATE UNIQUE INDEX "EntityAttachment_subject_singular_role_key" ON "EntityAttachment" USING btree ("subjectEntityId","role") WHERE "EntityAttachment"."role" IN ('cover', 'logo') AND "EntityAttachment"."deletedAt" IS NULL;
CREATE UNIQUE INDEX "EntityAttachment_subject_idempotency_key" ON "EntityAttachment" USING btree ("subjectEntityId","idempotencyKey") WHERE "EntityAttachment"."idempotencyKey" IS NOT NULL AND "EntityAttachment"."deletedAt" IS NULL;
CREATE INDEX "EntityAttachment_subject_order_idx" ON "EntityAttachment" USING btree ("subjectEntityId","sortOrder");
CREATE INDEX "EntityAttachment_imageId_idx" ON "EntityAttachment" USING btree ("imageId");

ALTER TABLE "EntityAttachment" ADD CONSTRAINT "EntityAttachment_subjectEntityId_Entity_id_fk" FOREIGN KEY ("subjectEntityId") REFERENCES "public"."Entity"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "EntityAttachment" ADD CONSTRAINT "EntityAttachment_imageId_Image_id_fk" FOREIGN KEY ("imageId") REFERENCES "public"."Image"("id") ON DELETE no action ON UPDATE no action;

INSERT INTO "EntityAttachment"
  ("subjectEntityId", "imageId", "role", "sortOrder", "purpose", "documentKind", "createdAt", "updatedAt")
SELECT j."productId", j."imageId", 'attachment', j."sortOrder", j."purpose", NULL, j."createdAt", j."updatedAt"
FROM "ProductImage" j
WHERE j."deletedAt" IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM "EntityAttachment" a
    WHERE a."subjectEntityId" = j."productId" AND a."imageId" = j."imageId" AND a."deletedAt" IS NULL
  );

