-- Verify: every count pair is equal, and every other query returns no rows.
SELECT e."kind", count(*) FILTER (WHERE e."deletedAt" IS NULL) AS "liveIdentities"
FROM "Entity" e GROUP BY e."kind" ORDER BY e."kind";
SELECT count(*) AS "redirects" FROM "Entity" WHERE "mergedIntoId" IS NOT NULL;
SELECT count(*) AS "codelessTombstones" FROM "Entity" WHERE "shortcode" IS NULL;
SELECT
  (SELECT count(*) FROM "EntityAttachment" WHERE "deletedAt" IS NULL AND "role" = 'attachment') AS "galleryAttachments",
  ((SELECT count(*) FROM "ProductImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "LocationImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "GardenEntryImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "RecipeImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "MealImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "TaskImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "PurchaseImage" WHERE "deletedAt" IS NULL) + (SELECT count(*) FROM "ProjectImage" WHERE "deletedAt" IS NULL)) AS "legacyGalleryRows";
SELECT a."subjectEntityId" FROM "EntityAttachment" a
JOIN "Purchase" p ON p."id" = a."subjectEntityId"
WHERE a."documentKind" IS NULL;
SELECT tgrelid::regclass AS "table", count(*) AS "identityTriggers"
FROM pg_trigger WHERE tgname LIKE 'Entity\_identity\_%'
GROUP BY tgrelid HAVING count(*) <> 3;
